import { createHevyMcpServer } from "@hevy-mcp/core";
import { createHevyClient } from "@hevy-mcp/hevy-client";
import { z } from "zod";
import type { NodeTransport } from "./utils/arguments.js";

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});

/**
 * Create an unconnected MCP server for embedding in a Node application.
 *
 * This entry point intentionally contains no Node runtime bootstrap. It does
 * not read process state, probe Hevy, install process handlers, initialize
 * telemetry, or connect a transport. The embedding application owns those
 * concerns and the transport lifecycle.
 */
export function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	_transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	try {
		const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
		return Promise.resolve(
			createHevyMcpServer({
				createClient: ({ onLog }) =>
					createHevyClient({
						apiKey: validatedApiKey,
						onLog,
					}),
				lifecycleSignal,
			}),
		);
	} catch (error) {
		return Promise.reject(error);
	}
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runStdioServer(): Promise<void> {
	const { runStdioServer: run } = await import("./runtime.js");
	return run();
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runServer(): Promise<void> {
	const { runServer: run } = await import("./runtime.js");
	return run();
}

import { afterEach, describe, expect, it, vi } from "vitest";

const testDoubles = vi.hoisted(() => ({
	createHevyClient: vi.fn(() => ({ kind: "client" })),
	createHevyMcpServer: vi.fn(
		(options: {
			createClient: (context: { onLog: () => void }) => unknown;
		}) => {
			options.createClient({ onLog: vi.fn() });
			return { kind: "server" };
		},
	),
}));

vi.mock("@hevy-mcp/hevy-client", () => ({
	createHevyClient: testDoubles.createHevyClient,
}));
vi.mock("@hevy-mcp/core", () => ({
	createHevyMcpServer: testDoubles.createHevyMcpServer,
}));

// If the embedding entry ever eagerly imports the runtime bootstrap, this
// mock factory is evaluated and the test fails before any test can run.
vi.mock("./utils/telemetry.js", () => {
	throw new Error("embedding entry imported runtime telemetry");
});

import { createNodeMcpServer } from "./index.js";

describe("Node embedding entry", () => {
	afterEach(() => {
		vi.restoreAllMocks();
		testDoubles.createHevyClient.mockClear();
		testDoubles.createHevyMcpServer.mockClear();
	});

	it("imports and constructs without startup side effects", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const setTimeoutSpy = vi.spyOn(globalThis, "setTimeout");
		const setIntervalSpy = vi.spyOn(globalThis, "setInterval");
		const argv = [...process.argv];
		process.argv = ["node", "embedding-test", "--transport", "http"];
		process.env.HEVY_API_KEY = "environment-sentinel";

		await expect(
			createNodeMcpServer({ apiKey: "programmatic-key" }),
		).resolves.toEqual({ kind: "server" });

		expect(fetchSpy).not.toHaveBeenCalled();
		expect(setTimeoutSpy).not.toHaveBeenCalled();
		expect(setIntervalSpy).not.toHaveBeenCalled();
		expect(testDoubles.createHevyClient).toHaveBeenCalledWith({
			apiKey: "programmatic-key",
			onLog: expect.any(Function),
		});
		expect(testDoubles.createHevyMcpServer).toHaveBeenCalledOnce();

		process.argv = argv;
		delete process.env.HEVY_API_KEY;
	});

	it("validates the supplied key locally", async () => {
		await expect(createNodeMcpServer({ apiKey: "" })).rejects.toThrow(
			"Hevy API key is required",
		);
		expect(testDoubles.createHevyClient).not.toHaveBeenCalled();
		expect(testDoubles.createHevyMcpServer).not.toHaveBeenCalled();
	});
});

import { runServer } from "./runtime.js";
import { MissingHevyApiKeyError } from "./utils/config.js";
import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import { flushTelemetry } from "./utils/telemetry.js";

void runServer().catch(async (error) => {
	if (error instanceof MissingHevyApiKeyError) {
		console.error(error.message);
	} else {
		console.error("Fatal error in main()", createSafeErrorDiagnostic(error));
	}
	try {
		await flushTelemetry();
	} catch {
		// Preserve the original fatal exit when telemetry flushing fails.
	}
	process.exit(1);
});

