const collectorToken =
	z.string().safeParse(readBuildGlobal(() => __OTEL_COLLECTOR_TOKEN__)).data ??
	process.env.OTEL_COLLECTOR_TOKEN ??
	"";

const COLLECTOR_ENDPOINT = "https://otel.chrisdoc.dev/v1";
