			),
		skipOpenTelemetrySetup: true,
		registerEsmLoaderHooks: false,
		ignoreErrors: ["EPIPE", "broken pipe"],
	});

	const spanProcessors: SpanProcessor[] = [];

	// OTel Collector → Honeycomb traces — only if token is available
	if (collectorToken) {

